import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.100.1';
import { getCorsHeaders, handleCorsPreflightRequest } from '../_shared/cors.ts';
// @deno-types="https://esm.sh/jspdf@2.5.2"
import { jsPDF } from 'https://esm.sh/jspdf@2.5.2';
import { checkServiceRoleOrAdmin } from '../_shared/auth.ts';

/**
 * Edge Function: generate-purchase-contract
 * 
 * Generates a professional, German-language purchase contract (Kaufvertrag)
 * between seller and buyer (typically dealer) after a successful auction.
 *
 * Features:
 * - KuechenWert logo embedded in header
 * - Sequential contract numbers (KV-YYYY-NNNNN) from DB sequence
 * - Dealer customer number (Kundennummer) displayed on contract
 * - VAT wording from listing (mwst_ausweisbar) for commercial sellers
 * - Annex A: cover image + structured listing export
 * - Contract stored in purchase_contracts table
 * - PDF uploaded to Supabase Storage
 * 
 * Called by: close-auction (after invoice flow, when status = sold)
 * Auth: service_role or admin
 */

interface ContractRequest {
  auctionId: string;
  kitchenId: string;
  buyerId: string;   // dealer
  sellerId: string;  // private seller
  salePrice: number; // winning bid amount
}

// ─── Color constants (matching KuechenWert brand) ──────────────────────────
const BRAND = { r: 15, g: 79, b: 92 };       // #0f4f5c
const ACCENT = { r: 31, g: 138, b: 162 };     // #1f8aa2
const TEXT_DARK = { r: 31, g: 41, b: 55 };
const TEXT_MED = { r: 75, g: 85, b: 99 };
const TEXT_LIGHT = { r: 107, g: 114, b: 128 };
const LIGHT_BG = { r: 249, g: 250, b: 251 };  // #f9fafb

// ─── KuechenWert Logo (Original, 482x130px PNG) ──────────────────────────
const LOGO_BASE64 = 'data:image/png;base64,';

// ─── KuechenWert Logo White (for dark backgrounds, 482x130px PNG) ─────────
const LOGO_WHITE_BASE64 = 'data:image/png;base64,';

function formatCurrency(amount: number): string {
  return Number(amount).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
}

function formatDate(dateStr?: string | null): string {
  if (!dateStr) return '–';
  return new Date(dateStr).toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

function formatMonthYear(dateStr?: string | null): string {
  if (!dateStr) return '–';
  const m = /^(\d{4})-(\d{2})/.exec(dateStr);
  if (m) return `${m[2]}.${m[1]}`;
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return String(dateStr);
    const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    return `${mm}.${d.getUTCFullYear()}`;
  } catch {
    return String(dateStr);
  }
}

function todayFormatted(): string {
  return new Date().toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

function isoTimestamp(): string {
  return new Date().toISOString();
}

/**
 * Convert a number to German words for legal contracts.
 * Supports amounts up to 999.999,99 €.
 */
function numberToWords(n: number): string {
  const ones = ['', 'ein', 'zwei', 'drei', 'vier', 'fünf', 'sechs', 'sieben', 'acht', 'neun', 'zehn',
    'elf', 'zwölf', 'dreizehn', 'vierzehn', 'fünfzehn', 'sechzehn', 'siebzehn', 'achtzehn', 'neunzehn'];
  const tens = ['', 'zehn', 'zwanzig', 'dreißig', 'vierzig', 'fünfzig', 'sechzig', 'siebzig', 'achtzig', 'neunzig'];

  function twoDigits(num: number): string {
    if (num < 20) return ones[num];
    const t = Math.floor(num / 10);
    const o = num % 10;
    if (o === 0) return tens[t];
    if (o === 1) return 'ein' + 'und' + tens[t];
    return ones[o] + 'und' + tens[t];
  }

  function threeDigits(num: number): string {
    if (num === 0) return '';
    if (num < 100) return twoDigits(num);
    const h = Math.floor(num / 100);
    const rest = num % 100;
    const hStr = ones[h] + 'hundert';
    if (rest === 0) return hStr;
    return hStr + twoDigits(rest);
  }

  const euros = Math.floor(n);
  const cents = Math.round((n - euros) * 100);

  let result = '';

  if (euros === 0) {
    result = 'null';
  } else if (euros === 1) {
    result = 'ein';
  } else {
    const thousands = Math.floor(euros / 1000);
    const remainder = euros % 1000;

    if (thousands > 0) {
      if (thousands === 1) {
        result += 'eintausend';
      } else {
        result += threeDigits(thousands) + 'tausend';
      }
    }
    if (remainder > 0) {
      result += threeDigits(remainder);
    }
  }

  // Capitalize first letter
  result = result.charAt(0).toUpperCase() + result.slice(1);

  if (cents > 0) {
    result += ' Euro und ' + twoDigits(cents) + ' Cent';
  } else {
    result += ' Euro';
  }

  return result;
}

/** JPEG SOF0 / SOF2 dimensions (sufficient for most listing photos). */
function readJpegDimensions(u8: Uint8Array): { w: number; h: number } | null {
  let i = 2;
  while (i + 9 < u8.length) {
    if (u8[i] !== 0xff) return null;
    const marker = u8[i + 1];
    const len = (u8[i + 2] << 8) | u8[i + 3];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      const h = (u8[i + 5] << 8) | u8[i + 6];
      const w = (u8[i + 7] << 8) | u8[i + 8];
      return { w, h };
    }
    if (len < 2) return null;
    i += 2 + len;
  }
  return null;
}

function readPngDimensions(u8: Uint8Array): { w: number; h: number } | null {
  if (u8.length < 24 || u8[0] !== 0x89) return null;
  const sig = String.fromCharCode(u8[1], u8[2], u8[3]);
  if (sig !== 'PNG') return null;
  const w = (u8[16] << 24) | (u8[17] << 16) | (u8[18] << 8) | u8[19];
  const h = (u8[20] << 24) | (u8[21] << 16) | (u8[22] << 8) | u8[23];
  return { w, h };
}

async function fetchCoverImageForPdf(
  imageUrl: string,
): Promise<{ dataUrl: string; fmt: 'JPEG' | 'PNG'; w: number; h: number } | null> {
  try {
    const r = await fetch(imageUrl, { signal: AbortSignal.timeout(20000) });
    if (!r.ok) {
      console.warn('Cover image HTTP', r.status, imageUrl);
      return null;
    }
    const buf = new Uint8Array(await r.arrayBuffer());
    if (buf.length < 24) return null;
    const isPng = buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;
    const fmt: 'JPEG' | 'PNG' = isPng ? 'PNG' : 'JPEG';
    let dims = isPng ? readPngDimensions(buf) : readJpegDimensions(buf);
    if (!dims) dims = { w: 4, h: 3 };

    let binaryString = '';
    const chunkSize = 4096;
    for (let i = 0; i < buf.length; i += chunkSize) {
      binaryString += String.fromCharCode(...buf.subarray(i, i + chunkSize));
    }
    const b64 = btoa(binaryString);
    const mime = isPng ? 'image/png' : 'image/jpeg';
    return { dataUrl: `data:${mime};base64,${b64}`, fmt, w: dims.w, h: dims.h };
  } catch (e) {
    console.warn('fetchCoverImageForPdf failed:', e);
    return null;
  }
}

function fitImageToBox(
  natW: number,
  natH: number,
  maxW: number,
  maxH: number,
): { w: number; h: number } {
  const ratio = natW / natH;
  let w = maxW;
  let h = w / ratio;
  if (h > maxH) {
    h = maxH;
    w = h * ratio;
  }
  return { w, h };
}

/** Plain-text export of listing fields for contract annex (German labels). */
function buildKitchenListingAppendix(m: Record<string, unknown>): string {
  const out: string[] = [];
  const add = (label: string, val: unknown) => {
    if (val === null || val === undefined || val === '') return;
    if (typeof val === 'boolean') {
      if (val) out.push(`${label}: Ja`);
      return;
    }
    if (typeof val === 'number') {
      out.push(`${label}: ${val.toLocaleString('de-DE')}`);
      return;
    }
    out.push(`${label}: ${String(val).trim()}`);
  };

  add('Inseratsnummer', m.listing_number);
  add('Hersteller', m.manufacturer);
  add('Modell', m.model);
  add('Aufbauart', m.body_type);
  add('Verkaufstyp', m.sale_type);
  add('Konto-Typ (Plattform)', m.account_type);
  add('Standort (Freitext)', m.location);
  add('Verfügbar ab', m.available_from);
  add('Inseratspreis / Angebotspreis (€)', m.price);
  add('Baujahr', m.year);
  add('Kilometerstand', m.mileage != null ? `${Number(m.mileage).toLocaleString('de-DE')} km` : null);
  add('Zustand', m.condition);
  add('Kraftstoff', m.fuel_type);
  add('Tankinhalt (l)', m.fuel_tank_capacity_liters);
  add('Emissionsklasse', m.emission_class);
  add('Getriebe', m.transmission);
  add('Leistung (kW)', m.power_kw);
  add('Leistung (PS)', m.engine_power_hp);
  add('Hubraum (ccm)', m.engine_displacement_ccm);
  add('Basisfahrzeug', m.base_vehicle);
  add('Erstzulassung', m.first_registration ? formatMonthYear(m.first_registration) : null);
  add('Letzte HU', m.last_tuev_date ? formatMonthYear(m.last_tuev_date) : null);
  add('HU gültig bis', m.tuev_valid_until ? formatMonthYear(m.tuev_valid_until) : null);
  add('Vorbesitzer', m.previous_owners);
  add('Unfallfrei', m.accident_free === true ? 'Ja' : m.accident_free === false ? 'Nein' : null);
  add('Nichtraucher', m.non_smoker === true ? 'Ja' : m.non_smoker === false ? 'Nein' : null);
  add('Checkheft / Service', m.service_history_available === true ? 'Ja' : null);
  add('Schäden bekannt', m.has_damage === true ? 'Ja' : m.has_damage === false ? 'Nein' : null);
  add('Schaden-/Mängeltext', m.damage_summary);
  add('Markisenlänge (m)', m.awning_length_m);
  add('Länge (m)', m.length_m);
  add('Breite (m)', m.width_m);
  add('Höhe (m)', m.height_m);
  add('Gewicht (kg)', m.weight_kg);
  add('Nutzlast (kg)', m.payload_kg);
  add('Achsen', m.number_of_axles);
  add('Sitze', m.seats);
  add('Schlafplätze', m.sleeping_places);
  add('Betten / Bettenbeschreibung', m.beds_description);
  add('Frischwasser (l)', m.water_tank_liters);
  add('Grauwasser (l)', m.grey_water_capacity_liters);
  add('Hauptreifen', m.main_tires);
  add('Zweitreifen', m.second_tires);
  add('Batterie (Ah)', m.battery_capacity_ah);
  add('Solar (W)', m.solar_power_watts);
  add('Heizung', m.heating_type);
  add('Küche vorhanden', m.has_kitchen);
  add('Kühlschranktyp', m.refrigerator_type);
  add('Klima', m.air_conditioning_type);
  add('Gas', m.gas_system);
  add('Standort PLZ', m.postal_code);
  add('Ort', m.city);
  add('Land', m.country);
  add('FIN', m.vehicle_identification_number);
  add('Kennzeichen', m.license_plate);
  add('Sofortkaufpreis (€)', m.instant_price);
  add('Mindestpreis / Limit (€)', m.reserve_price);
  add('Zusätzliche Ausstattung / Hinweise', m.additional_equipment);

  const equip: [string, unknown, string][] = [
    ['has_bathroom', m.has_bathroom, 'Bad'],
    ['has_toilet', m.has_toilet, 'WC'],
    ['has_shower', m.has_shower, 'Dusche'],
    ['has_solar', m.has_solar, 'Solar'],
    ['has_awning', m.has_awning, 'Markise'],
    ['has_awning_tent', m.has_awning_tent, 'Vorzelt'],
    ['has_roof_ac', m.has_roof_ac, 'Dachklima'],
    ['has_stand_ac', m.has_stand_ac, 'Standklima'],
    ['has_bike_rack', m.has_bike_rack, 'Fahrradträger'],
    ['has_garage', m.has_garage, 'Garage/Stauraum'],
    ['has_tv', m.has_tv, 'TV'],
    ['has_backup_camera', m.has_backup_camera, 'Rückfahrkamera'],
    ['has_parking_sensors', m.has_parking_sensors, 'Einparkhilfe'],
    ['has_cruise_control', m.has_cruise_control, 'Tempomat'],
    ['has_central_locking', m.has_central_locking, 'Zentralverriegelung'],
    ['has_inverter', m.has_inverter, 'Wechselrichter'],
    ['has_navigation', m.has_navigation, 'Navigation'],
    ['has_satellite', m.has_satellite, 'Sat-Anlage'],
    ['has_airbag', m.has_airbag, 'Airbag'],
    ['has_alarm', m.has_alarm, 'Alarm'],
    ['has_esp', m.has_esp, 'ESP'],
    ['has_swivel_seats', m.has_swivel_seats, 'Drehsitze'],
    ['has_markise', m.has_markise, 'Markise (Alt)'],
    ['has_heating', m.has_heating, 'Heizung vorhanden'],
    ['has_air_conditioning', m.has_air_conditioning, 'Klimaanlage'],
    ['has_tuev', m.has_tuev, 'TÜV relevant'],
  ];
  for (const [, v, label] of equip) {
    if (v === true) out.push(`Ausstattung: ${label}`);
  }

  if (m.description && String(m.description).trim()) {
    out.push('');
    out.push('--- Beschreibungstext aus dem Inserat ---');
    out.push(String(m.description).trim());
  }

  if (m.mwst_ausweisbar === true) {
    out.push('');
    out.push('Hinweis Inserat: Umsatzsteuer wird auf der Kaufrechnung gesondert ausgewiesen.');
  } else if (m.mwst_ausweisbar === false) {
    out.push('');
    out.push('Hinweis Inserat: Verkauf ohne gesonderte Umsatzsteuerausweisung (z. B. Differenzbesteuerung / Kleinunternehmer).');
  }

  return out.join('\n');
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return handleCorsPreflightRequest(req);
  }

  const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? '';
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';

  // ─── Auth check: must be service_role (cron/internal) or authenticated admin ───
  const authResult = await checkServiceRoleOrAdmin(req, getCorsHeaders(req));
  if (!authResult.authorized) {
    return authResult.response;
  }

  try {
    // ─── Initialize Supabase client ──────────────────────────────
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const { auctionId, kitchenId, buyerId, sellerId, salePrice }: ContractRequest = await req.json();

    if (!auctionId || !kitchenId || !buyerId || !sellerId || !salePrice) {
      throw new Error('All fields are required: auctionId, kitchenId, buyerId, sellerId, salePrice');
    }

    console.log('Generating purchase contract for auction:', auctionId);

    // ─── Fetch all required data ───────────────────────────────────
    const { data: kitchen, error: mhError } = await supabase
      .from('kitchens')
      .select('*')
      .eq('id', kitchenId)
      .single();

    if (mhError || !kitchen) throw new Error(`Kitchen not found: ${mhError?.message}`);

    const { data: sellerRoles } = await supabase
      .from('user_roles')
      .select('role')
      .eq('user_id', sellerId);
    const sellerIsDealer = (sellerRoles ?? []).some((r) => r.role === 'dealer');

    const { data: photoRows } = await supabase
      .from('kitchen_photos')
      .select('url, is_primary, display_order')
      .eq('kitchen_id', kitchenId)
      .order('is_primary', { ascending: false })
      .order('display_order', { ascending: true });

    const coverUrl = photoRows?.find((p) => p.url)?.url ?? null;
    let coverForPdf: Awaited<ReturnType<typeof fetchCoverImageForPdf>> = null;
    if (coverUrl) {
      coverForPdf = await fetchCoverImageForPdf(coverUrl);
    }
    const listingAppendixText = buildKitchenListingAppendix(
      kitchen as unknown as Record<string, unknown>,
    );

    const { data: seller, error: sellerError } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', sellerId)
      .single();

    if (sellerError || !seller) throw new Error(`Seller not found: ${sellerError?.message}`);

    const { data: buyer, error: buyerError } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', buyerId)
      .single();

    if (buyerError || !buyer) throw new Error(`Buyer not found: ${buyerError?.message}`);

    const { data: settings } = await supabase
      .from('site_settings')
      .select('*')
      .limit(1)
      .maybeSingle();

    // ─── Generate sequential contract number from DB ──────────────
    const { data: contractNumData, error: contractNumError } = await supabase
      .rpc('generate_contract_number');

    if (contractNumError) {
      console.error('Failed to generate contract number:', contractNumError);
      throw new Error(`Failed to generate contract number: ${contractNumError.message}`);
    }

    const contractNumber = contractNumData as string;
    console.log('Generated contract number:', contractNumber);

    // ─── Prepare data ──────────────────────────────────────────────
    const siteName = settings?.site_name || 'KuechenWert';
    const siteAddress = settings?.company_address || 'Hannoversche Straße 106';
    const siteCity = settings?.company_city || 'Hannover';
    const siteZip = settings?.company_postal_code || '30627';
    const managingDirector = settings?.managing_director || '';
    const hrbNumber = settings?.hrb_number || '';
    const contactEmail = settings?.contact_email || 'info@kuechenwert24.de';
    const sitePhone = settings?.support_phone || '0511 / 51532476';

    const sellerName = `${seller.first_name || ''} ${seller.last_name || ''}`.trim() || 'Verkäufer';
    const sellerAddress = [seller.address_street, `${seller.address_zip || ''} ${seller.address_city || ''}`.trim()].filter(Boolean).join(', ') || 'Adresse nicht hinterlegt';
    const sellerEmail = seller.email || '';
    const sellerPhone = seller.phone || '';

    const buyerName = buyer.company_name || `${buyer.first_name || ''} ${buyer.last_name || ''}`.trim() || 'Käufer';
    const buyerAddress = [buyer.company_street, `${buyer.company_zip || ''} ${buyer.company_city || ''}`.trim()].filter(Boolean).join(', ') || 'Adresse nicht hinterlegt';
    const buyerEmail = buyer.email || '';
    const buyerPhone = buyer.phone || '';
    const buyerTaxId = buyer.tax_id || '';
    const buyerCustomerNumber = buyer.customer_number || '';

    const vehicleName = `${kitchen.manufacturer} ${kitchen.model}`;
    const vin = kitchen.vehicle_identification_number || 'Nicht angegeben';
    const licensePlate = kitchen.license_plate || 'Nicht angegeben';
    const firstReg = formatMonthYear(kitchen.first_registration);
    const mileage = kitchen.mileage ? `${kitchen.mileage.toLocaleString('de-DE')} km` : 'Nicht angegeben';
    const bodyType = kitchen.body_type || 'Nicht angegeben';
    const year = kitchen.year ? String(kitchen.year) : 'Nicht angegeben';
    const fuelType = kitchen.fuel_type || 'Nicht angegeben';
    const weight = kitchen.weight_kg ? `${kitchen.weight_kg.toLocaleString('de-DE')} kg` : 'Nicht angegeben';

    const today = todayFormatted();
    const timestamp = isoTimestamp();

    // ─── Generate PDF ──────────────────────────────────────────────
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pw = 210;
    const ml = 20;
    const mr = 20;
    const cw = pw - ml - mr;
    let y = 0;

    // ── Helper functions ───────────────────────────────────────────
    const addHeader = () => {
      // White area for logo (top 20mm)
      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, pw, 20, 'F');

      // KuechenWert logo (482x130 = ratio 3.71:1, target height ~12mm)
      try {
        const logoH = 12;
        const logoW = logoH * (482 / 130); // ~44.5mm
        doc.addImage(LOGO_BASE64, 'PNG', ml, 4, logoW, logoH);
      } catch (_e) {
        // Fallback: text if image fails
        doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
        doc.setFontSize(14);
        doc.setFont('helvetica', 'bold');
        doc.text(siteName, ml, 13);
      }

      // Contract info on the right (in white area)
      doc.setTextColor(TEXT_MED.r, TEXT_MED.g, TEXT_MED.b);
      doc.setFontSize(7);
      doc.setFont('helvetica', 'normal');
      doc.text(`Vertragsnr.: ${contractNumber}`, pw - mr, 8, { align: 'right' });
      doc.text(`Datum: ${today}`, pw - mr, 12, { align: 'right' });
      if (buyerCustomerNumber) {
        doc.text(`Kundennr.: ${buyerCustomerNumber}`, pw - mr, 16, { align: 'right' });
      }

      // Dark brand bar below logo
      doc.setFillColor(BRAND.r, BRAND.g, BRAND.b);
      doc.rect(0, 20, pw, 3, 'F');
      // Accent line
      doc.setFillColor(ACCENT.r, ACCENT.g, ACCENT.b);
      doc.rect(0, 23, pw, 1, 'F');
    };

    const addFooter = (pageNum: number, totalPages: number) => {
      const footerY = 283;
      doc.setFillColor(BRAND.r, BRAND.g, BRAND.b);
      doc.rect(0, footerY, pw, 14, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFontSize(6);
      doc.setFont('helvetica', 'normal');
      const footerLeft = [`${siteName} – WohnWert GmbH`];
      if (managingDirector) footerLeft.push(`GF: ${managingDirector}`);
      if (hrbNumber) footerLeft.push(`AG Hildesheim, HRB ${hrbNumber}`);
      doc.text(footerLeft.join(' · '), ml, footerY + 5);
      doc.text(`Seite ${pageNum} von ${totalPages}`, pw - mr, footerY + 5, { align: 'right' });
      doc.text([contactEmail, sitePhone].filter(Boolean).join(' · '), pw / 2, footerY + 10, { align: 'center' });
    };

    const sectionTitle = (title: string) => {
      if (y > 255) {
        doc.addPage();
        addHeader();
        y = 32;
      }
      y += 3;
      doc.setFillColor(LIGHT_BG.r, LIGHT_BG.g, LIGHT_BG.b);
      doc.rect(ml, y - 4, cw, 7, 'F');
      doc.setDrawColor(ACCENT.r, ACCENT.g, ACCENT.b);
      doc.line(ml, y - 4, ml + cw, y - 4);
      doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
      doc.setFontSize(10);
      doc.setFont('helvetica', 'bold');
      doc.text(title, ml + 3, y);
      y += 6;
    };

    const detailRow = (label: string, value: string) => {
      if (y > 270) {
        doc.addPage();
        addHeader();
        y = 32;
      }
      doc.setTextColor(TEXT_LIGHT.r, TEXT_LIGHT.g, TEXT_LIGHT.b);
      doc.setFontSize(8);
      doc.setFont('helvetica', 'normal');
      doc.text(label, ml + 3, y);
      doc.setTextColor(TEXT_DARK.r, TEXT_DARK.g, TEXT_DARK.b);
      doc.setFont('helvetica', 'bold');
      doc.text(value, ml + 55, y);
      y += 5;
    };

    const paragraphText = (text: string, indent = 3) => {
      if (y > 265) {
        doc.addPage();
        addHeader();
        y = 32;
      }
      doc.setTextColor(TEXT_MED.r, TEXT_MED.g, TEXT_MED.b);
      doc.setFontSize(8);
      doc.setFont('helvetica', 'normal');
      const lines = doc.splitTextToSize(text, cw - indent * 2);
      for (const line of lines) {
        if (y > 275) {
          doc.addPage();
          addHeader();
          y = 32;
        }
        doc.text(line, ml + indent, y);
        y += 4;
      }
      y += 1;
    };

    // ── PAGE 1 ─────────────────────────────────────────────────────
    addHeader();
    y = 32;

    // Title
    doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('Kaufvertrag', pw / 2, y, { align: 'center' });
    y += 5;
    doc.setFontSize(10);
    doc.setTextColor(ACCENT.r, ACCENT.g, ACCENT.b);
    doc.text('über ein gebrauchtes Wohnmobil / Wohnwagen', pw / 2, y, { align: 'center' });
    y += 4;
    doc.setFontSize(7);
    doc.setTextColor(TEXT_LIGHT.r, TEXT_LIGHT.g, TEXT_LIGHT.b);
    doc.text(`Vermittelt über ${siteName} (WohnWert GmbH) · ${siteAddress}, ${siteZip} ${siteCity}`, pw / 2, y, { align: 'center' });
    y += 8;

    // ── §1 Vertragsparteien ────────────────────────────────────────
    sectionTitle('§ 1 Vertragsparteien');

    doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.text('Verkäufer (nachfolgend „Verkäufer“):', ml + 3, y);
    y += 5;
    detailRow('Name', sellerName);
    detailRow('Anschrift', sellerAddress);
    if (sellerPhone) detailRow('Telefon', sellerPhone);
    detailRow('E-Mail', sellerEmail);
    y += 3;

    doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.text('Käufer (nachfolgend „Käufer“):', ml + 3, y);
    y += 5;
    detailRow('Firma / Name', buyerName);
    if (buyerCustomerNumber) detailRow('Kundennummer', buyerCustomerNumber);
    detailRow('Anschrift', buyerAddress);
    if (buyerPhone) detailRow('Telefon', buyerPhone);
    detailRow('E-Mail', buyerEmail);
    if (buyerTaxId) detailRow('USt-IdNr.', buyerTaxId);
    y += 2;

    // ── §2 Vertragsgegenstand ──────────────────────────────────────
    sectionTitle('§ 2 Vertragsgegenstand');

    paragraphText('Der Verkäufer verkauft dem Käufer das nachstehend beschriebene Fahrzeug:');
    y += 1;
    detailRow('Hersteller / Modell', vehicleName);
    detailRow('Baujahr', year);
    detailRow('Aufbauart', bodyType);
    detailRow('Erstzulassung', firstReg);
    detailRow('Kilometerstand', mileage);
    detailRow('Fahrgestellnr. (VIN)', vin);
    detailRow('Kennzeichen', licensePlate);
    detailRow('Kraftstoff', fuelType);
    detailRow('Zul. Gesamtgewicht', weight);
    y += 2;
    paragraphText(
      'Als Anlage A werden das Titelbild aus dem Inserat sowie ein vollständiger Abdruck der auf der Plattform veröffentlichten Fahrzeugangaben Bestandteil dieses Vertrages.',
    );
    y += 1;

    // ── §3 Kaufpreis und Zahlung ──────────────────────────────────
    sectionTitle('§ 3 Kaufpreis und Zahlung');

    paragraphText(`Der Kaufpreis beträgt ${formatCurrency(salePrice)} (in Worten: ${numberToWords(salePrice)}).`);
    const isDirectFestpreis = kitchen.sale_type === 'instant';
    const isPriceProposal = kitchen.sale_type === 'price_proposal';
    const isFestpreisOrProposal = isDirectFestpreis || isPriceProposal || kitchen.sale_channel === 'instant_price';
    paragraphText(isPriceProposal
      ? 'Der Kaufpreis wurde durch Preisverhandlung über die Plattform ' + siteName + ' vereinbart und ist von beiden Parteien als verbindlich anerkannt.'
      : isDirectFestpreis || kitchen.sale_channel === 'instant_price'
        ? 'Der Kaufpreis entspricht dem auf der Plattform ' + siteName + ' veröffentlichten Festpreis und ist von beiden Parteien als verbindlich anerkannt.'
        : 'Der Kaufpreis wurde im Rahmen einer Online-Auktion über die Plattform ' + siteName + ' ermittelt und ist von beiden Parteien als verbindlich anerkannt.'
    );
    if (sellerIsDealer) {
      const ma = kitchen.mwst_ausweisbar;
      if (ma === true) {
        paragraphText(
          'Der Verkäufer handelt gewerblich. Im Inserat ist angegeben, dass die Umsatzsteuer auf der Kaufrechnung gesondert ausgewiesen wird. Der zwischen den Parteien vereinbarte Kaufpreis bezieht sich auf diese Angabe; die konkrete steuerliche Abrechnung ergibt sich aus der Rechnung des Verkäufers.',
        );
      } else if (ma === false) {
        paragraphText(
          'Der Verkäufer handelt gewerblich. Im Inserat ist angegeben, dass keine Umsatzsteuer gesondert ausgewiesen wird (z. B. Differenzbesteuerung nach dem Umsatzsteuergesetz oder Kleinunternehmerregelung). Der vereinbarte Kaufpreis entspricht den Angaben im Inserat.',
        );
      } else {
        paragraphText(
          'Der Verkäufer handelt gewerblich. Zur Ausweisung der Umsatzsteuer verweisen die Parteien auf die Angaben im Inserat und auf die Kaufrechnung des Verkäufers.',
        );
      }
    } else {
      paragraphText(
        'Der Verkäufer handelt als Privatperson; es wird keine Umsatzsteuer ausgewiesen. Der Kaufpreis versteht sich als Bruttobetrag. Dem Käufer bleibt es vorbehalten, die gesetzlichen Regelungen zur Differenzbesteuerung anzuwenden.',
      );
    }
    paragraphText('Die Zahlung des Kaufpreises wird unmittelbar zwischen Käufer und Verkäufer abgewickelt. Die Parteien wählen einvernehmlich eine der folgenden Zahlungsarten: (a) Überweisung des vollständigen Kaufpreises auf ein vom Verkäufer benanntes Bankkonto innerhalb von 7 Werktagen nach ' + (isFestpreisOrProposal ? 'Vertragsabschluss' : 'Zuschlag') + ', oder (b) Barzahlung des vollständigen Kaufpreises bei der Fahrzeugübergabe gegen schriftliche Quittung. Die Übergabe des Fahrzeugs erfolgt in beiden Fällen erst nach vollständigem Zahlungseingang bzw. Erhalt des Kaufpreises (siehe §4). ' + siteName + ' tritt ausschließlich als Vermittler auf und ist an der Zahlungsabwicklung nicht beteiligt.');
    y += 1;

    // ── §4 Übergabe ───────────────────────────────────────────────
    sectionTitle('§ 4 Übergabe und Eigentumsübergang');

    paragraphText('Die Übergabe des Fahrzeugs erfolgt nach vollständiger Zahlung des Kaufpreises. Der Eigentumsübergang erfolgt mit der Übergabe des Fahrzeugs und aller zugehörigen Dokumente (Fahrzeugbrief, Fahrzeugschein, Serviceheft, sämtliche Schlüssel).');
    paragraphText('Der Verkäufer verpflichtet sich, das Fahrzeug im vereinbarten Zustand zu übergeben. Der Käufer hat das Recht, das Fahrzeug vor der Übergabe zu besichtigen.');
    paragraphText('Die Übergabe wird in einem separaten Übergabeprotokoll dokumentiert, das von beiden Parteien zu unterzeichnen ist und als Anlage zu diesem Vertrag gilt. Das Übergabeprotokoll wird über die Plattform ' + siteName + ' bereitgestellt.');
    y += 1;

    // ── §5 Gewährleistung ──────────────────────────────────────────
    sectionTitle('§ 5 Gewährleistung und Haftung');

    paragraphText('Das Fahrzeug wird unter Ausschluss jeglicher Sachmängelhaftung verkauft. Dieser Ausschluss gilt nicht für Schadensersatzansprüche aus Verletzung des Lebens, des Körpers oder der Gesundheit und bei vorsätzlich oder grob fahrlässig verursachten Schäden des Verkäufers.');
    paragraphText('Der Verkäufer versichert, dass ihm keine verdeckten Mängel bekannt sind, die er dem Käufer nicht mitgeteilt hat. Bekannte Mängel und Schäden sind im Inserat auf ' + siteName + ' dokumentiert.');
    if (kitchen.has_damage && kitchen.damage_summary) {
      paragraphText(`Bekannte Schäden/Mängel: ${kitchen.damage_summary}`);
    }
    y += 1;

    // ── §6 Sonstige Vereinbarungen ─────────────────────────────────
    sectionTitle('§ 6 Sonstige Vereinbarungen');

    paragraphText('Der Verkäufer versichert, dass das Fahrzeug sein Eigentum ist und frei von Rechten Dritter (z.B. Pfandrechte, Sicherungsübereignungen). Das Fahrzeug ist nicht als gestohlen gemeldet.');
    paragraphText(`${kitchen.accident_free ? 'Der Verkäufer versichert, dass das Fahrzeug unfallfrei ist.' : 'Der Verkäufer hat angegeben, dass das Fahrzeug nicht unfallfrei ist. Details sind im Inserat dokumentiert.'}`);
    paragraphText(`Anzahl der Vorbesitzer: ${kitchen.previous_owners !== null && kitchen.previous_owners !== undefined ? kitchen.previous_owners : 'Nicht angegeben'}.`);
    paragraphText('Der Verkäufer verpflichtet sich, das Fahrzeug bis zur Übergabe ordnungsgemäß zu versichern und keine wesentlichen Veränderungen am Fahrzeug vorzunehmen.');
    y += 1;

    // ── §7 Vermittlung ─────────────────────────────────────────────
    sectionTitle('§ 7 Vermittlung durch ' + siteName);

    paragraphText(`Dieser Kaufvertrag wurde über die Online-Plattform ${siteName} (${siteAddress}, ${siteZip} ${siteCity}) vermittelt. ${siteName} tritt ausschließlich als Vermittler auf und ist nicht Vertragspartei dieses Kaufvertrags.`);
    paragraphText(`Die Vermittlungsprovision wird separat zwischen ${siteName} und dem Käufer abgerechnet und ist nicht Bestandteil des in §3 genannten Kaufpreises.`);
    y += 1;

    // ── §8 Schlussbestimmungen ─────────────────────────────────────
    sectionTitle('§ 8 Schlussbestimmungen');

    paragraphText('Änderungen und Ergänzungen dieses Vertrages bedürfen der Schriftform. Mündliche Nebenabreden bestehen nicht. Sollte eine Bestimmung dieses Vertrages unwirksam sein oder werden, so wird die Wirksamkeit der übrigen Bestimmungen davon nicht berührt. An die Stelle der unwirksamen Bestimmung tritt eine wirksame Regelung, die dem wirtschaftlichen Zweck der unwirksamen Bestimmung am nächsten kommt.');
    paragraphText('Es gilt das Recht der Bundesrepublik Deutschland. Gerichtsstand ist, soweit gesetzlich zulässig, der Sitz des Vermittlers.');
    paragraphText(`Dieser Vertrag wurde in zwei gleichlautenden Ausfertigungen erstellt – je eine für den Verkäufer und den Käufer. Eine digitale Kopie wird über ${siteName} bereitgestellt.`);
    y += 3;

    // ── Anlage A (Inserat) ────────────────────────────────────────
    doc.addPage();
    addHeader();
    y = 32;
    sectionTitle('Anlage A – Inseratsunterlagen');

    paragraphText(
      'Nachfolgend das zum Zeitpunkt des ' + (isFestpreisOrProposal ? 'Kaufabschlusses' : 'Zuschlags') + ' auf ' +
        siteName +
        ' veröffentlichte Titelbild (sofern vorhanden) sowie ein strukturierter Abdruck der Inseratsdaten.',
    );

    if (coverForPdf) {
      const maxImgW = cw - 6;
      const maxImgH = 88;
      const { w: imgW, h: imgH } = fitImageToBox(coverForPdf.w, coverForPdf.h, maxImgW, maxImgH);
      if (y + imgH + 14 > 268) {
        doc.addPage();
        addHeader();
        y = 32;
      }
      doc.setTextColor(TEXT_LIGHT.r, TEXT_LIGHT.g, TEXT_LIGHT.b);
      doc.setFontSize(8);
      doc.setFont('helvetica', 'bold');
      doc.text('Titelbild', ml + 3, y);
      y += 4;
      try {
        doc.addImage(coverForPdf.dataUrl, coverForPdf.fmt, ml + 3, y, imgW, imgH);
        y += imgH + 6;
      } catch (_imgErr) {
        paragraphText('(Das Titelbild konnte technisch nicht eingebettet werden.)');
      }
    } else {
      paragraphText(
        'Zum Zeitpunkt der Vertragsgenerierung lag kein Titelbild im Inserat vor oder es konnte nicht geladen werden.',
      );
    }

    if (y > 248) {
      doc.addPage();
      addHeader();
      y = 32;
    }
    doc.setTextColor(BRAND.r, BRAND.g, BRAND.b);
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');
    doc.text('Daten-Auszug aus dem Inserat', ml + 3, y);
    y += 6;

    for (const rawLine of listingAppendixText.split('\n')) {
      const line = rawLine.trimEnd();
      if (line === '') {
        y += 2;
        if (y > 275) {
          doc.addPage();
          addHeader();
          y = 32;
        }
        continue;
      }
      paragraphText(line, 3);
    }

    y += 2;

    // ── Unterschriften ─────────────────────────────────────────────
    if (y > 220) {
      doc.addPage();
      addHeader();
      y = 32;
    }

    sectionTitle('Unterschriften');

    paragraphText(`Dieser Vertrag wurde elektronisch über die Plattform ${siteName} erstellt und gilt ${isPriceProposal ? 'mit Annahme des Preisvorschlags' : isFestpreisOrProposal ? 'mit Abschluss des Kaufvorgangs' : 'mit Zuschlag der Auktion'} als von beiden Parteien angenommen.`);
    y += 5;

    // Signature boxes
    const sigBoxWidth = (cw - 10) / 2;

    // Seller signature
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.3);
    doc.rect(ml, y, sigBoxWidth, 35);
    doc.setTextColor(TEXT_LIGHT.r, TEXT_LIGHT.g, TEXT_LIGHT.b);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.text('Verkäufer', ml + 3, y + 5);
    doc.setTextColor(TEXT_DARK.r, TEXT_DARK.g, TEXT_DARK.b);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text(sellerName, ml + 3, y + 12);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(TEXT_MED.r, TEXT_MED.g, TEXT_MED.b);
    doc.text(`Datum: ${today}`, ml + 3, y + 19);
    doc.text(`Zeitstempel: ${timestamp}`, ml + 3, y + 24);
    doc.text('Elektronisch bestätigt via ' + siteName, ml + 3, y + 29);

    // Buyer signature
    const buyerSigX = ml + sigBoxWidth + 10;
    doc.setDrawColor(200, 200, 200);
    doc.rect(buyerSigX, y, sigBoxWidth, 35);
    doc.setTextColor(TEXT_LIGHT.r, TEXT_LIGHT.g, TEXT_LIGHT.b);
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.text('Käufer', buyerSigX + 3, y + 5);
    doc.setTextColor(TEXT_DARK.r, TEXT_DARK.g, TEXT_DARK.b);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text(buyerName, buyerSigX + 3, y + 12);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(TEXT_MED.r, TEXT_MED.g, TEXT_MED.b);
    if (buyerCustomerNumber) {
      doc.text(`Kundennr.: ${buyerCustomerNumber}`, buyerSigX + 3, y + 17);
      doc.text(`Datum: ${today}`, buyerSigX + 3, y + 21);
      doc.text(`Zeitstempel: ${timestamp}`, buyerSigX + 3, y + 25);
      doc.text('Elektronisch bestätigt via ' + siteName, buyerSigX + 3, y + 29);
    } else {
      doc.text(`Datum: ${today}`, buyerSigX + 3, y + 19);
      doc.text(`Zeitstempel: ${timestamp}`, buyerSigX + 3, y + 24);
      doc.text('Elektronisch bestätigt via ' + siteName, buyerSigX + 3, y + 29);
    }

    y += 42;

    // ── Hinweis-Box am Ende ────────────────────────────────────────
    if (y < 260) {
      doc.setFillColor(LIGHT_BG.r, LIGHT_BG.g, LIGHT_BG.b);
      doc.rect(ml, y, cw, 16, 'F');
      doc.setDrawColor(ACCENT.r, ACCENT.g, ACCENT.b);
      doc.setLineWidth(0.4);
      doc.line(ml, y, ml, y + 16);
      doc.setTextColor(TEXT_MED.r, TEXT_MED.g, TEXT_MED.b);
      doc.setFontSize(6.5);
      doc.setFont('helvetica', 'italic');
      doc.text('Hinweis: Dieser Kaufvertrag wurde automatisch über die Plattform ' + siteName + ' generiert.', ml + 3, y + 4);
      doc.text('Bei Fragen wenden Sie sich bitte an ' + contactEmail + '. Dieses Dokument dient als rechtsverbindlicher', ml + 3, y + 8);
      doc.text('Kaufvertrag zwischen den oben genannten Parteien. Vertragsnummer: ' + contractNumber, ml + 3, y + 12);
    }

    // ── Add footers to all pages ───────────────────────────────────
    const totalPages = doc.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      addFooter(i, totalPages);
    }

    // ─── Output PDF ────────────────────────────────────────────────
    const pdfOutput = doc.output('arraybuffer');
    const pdfBytes = new Uint8Array(pdfOutput);

    // Upload to storage
    const fileName = `${sellerId}/${contractNumber.replace(/[^a-zA-Z0-9-]/g, '_')}.pdf`;

    const { error: uploadError } = await supabase.storage
      .from('purchase-contracts')
      .upload(fileName, pdfBytes, {
        contentType: 'application/pdf',
        upsert: true,
      });

    if (uploadError) {
      throw new Error(`Failed to upload contract PDF: ${uploadError.message}`);
    }

    // Create signed URL (valid for 10 years for legal documents)
    const { data: signedData, error: signedError } = await supabase.storage
      .from('purchase-contracts')
      .createSignedUrl(fileName, 10 * 365 * 24 * 60 * 60);

    if (signedError) {
      throw new Error(`Failed to create signed URL: ${signedError.message}`);
    }

    // Also create a buyer-accessible copy
    const buyerFileName = `${buyerId}/${contractNumber.replace(/[^a-zA-Z0-9-]/g, '_')}.pdf`;
    await supabase.storage
      .from('purchase-contracts')
      .upload(buyerFileName, pdfBytes, {
        contentType: 'application/pdf',
        upsert: true,
      });

    // Create buyer signed URL
    const { data: buyerSignedData } = await supabase.storage
      .from('purchase-contracts')
      .createSignedUrl(buyerFileName, 10 * 365 * 24 * 60 * 60);

    const contractUrl = signedData.signedUrl;
    const buyerContractUrl = buyerSignedData?.signedUrl || contractUrl;

    // Update kitchen record with contract URL and number
    await supabase
      .from('kitchens')
      .update({ contract_url: contractUrl, contract_number: contractNumber })
      .eq('id', kitchenId);

    // ─── Store contract in purchase_contracts table ────────────────
    const { error: insertError } = await supabase
      .from('purchase_contracts')
      .insert({
        contract_number: contractNumber,
        auction_id: auctionId,
        kitchen_id: kitchenId,
        buyer_id: buyerId,
        seller_id: sellerId,
        sale_price: salePrice,
        status: 'active',
        contract_url: contractUrl,
        buyer_contract_url: buyerContractUrl,
        storage_path: fileName,
        buyer_storage_path: buyerFileName,
        buyer_customer_number: buyerCustomerNumber,
        seller_name: sellerName,
        buyer_name: buyerName,
        vehicle_description: vehicleName,
      });

    if (insertError) {
      console.error('Failed to store contract record:', insertError);
      // Don't throw - the PDF was already generated and uploaded successfully
    }

    // Return PDF as base64 for email attachment
    // CRITICAL: Don't use btoa(String.fromCharCode(...pdfBytes)) — the spread operator
    // hits "Maximum call stack size exceeded" for PDFs larger than ~100KB.
    // Use chunked conversion instead.
    let binaryString = '';
    const chunkSize = 8192;
    for (let i = 0; i < pdfBytes.length; i += chunkSize) {
      const chunk = pdfBytes.subarray(i, i + chunkSize);
      binaryString += String.fromCharCode(...chunk);
    }
    const pdfBase64 = btoa(binaryString);

    console.log(`Purchase contract generated: ${contractNumber}`);

    return new Response(
      JSON.stringify({
        success: true,
        contractNumber,
        contractUrl,
        buyerContractUrl,
        pdfBase64,
      }),
      { headers: { ...getCorsHeaders(req), 'Content-Type': 'application/json' } }
    );
  } catch (error: any) {
    console.error('Error in generate-purchase-contract:', error);
    return new Response(
      JSON.stringify({ error: error.message }),
      {
        status: 500,
        headers: { ...getCorsHeaders(req), 'Content-Type': 'application/json' },
      }
    );
  }
});
